-- HIPA ERP sales invoice repair
-- Safe to run once in Supabase SQL Editor. It repairs databases that were created
-- before sales migration 0003 was applied.
BEGIN;

ALTER TABLE public."sales_salesinvoice"
  ADD COLUMN IF NOT EXISTS "settled_amount" numeric(14, 2) NOT NULL DEFAULT 0;
ALTER TABLE public."sales_salesinvoice"
  ALTER COLUMN "settled_amount" DROP DEFAULT;

CREATE TABLE IF NOT EXISTS public."sales_salessettlement" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "number" varchar(20) NOT NULL UNIQUE,
  "kind" varchar(6) NOT NULL,
  "amount" numeric(14, 2) NOT NULL CHECK ("amount" > 0),
  "date" date NOT NULL,
  "payment_method" varchar(13) NOT NULL,
  "reference" varchar(80) NOT NULL,
  "notes" varchar(500) NOT NULL,
  "status" varchar(10) NOT NULL,
  "created_at" timestamp with time zone NOT NULL,
  "updated_at" timestamp with time zone NOT NULL,
  "created_by_id" bigint NULL REFERENCES public."accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED,
  "customer_id" bigint NOT NULL REFERENCES public."customers_customer" ("id") DEFERRABLE INITIALLY DEFERRED,
  "invoice_id" bigint NOT NULL REFERENCES public."sales_salesinvoice" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX IF NOT EXISTS "sales_salessettlement_date_idx"
  ON public."sales_salessettlement" ("date");
CREATE INDEX IF NOT EXISTS "sales_salessettlement_status_idx"
  ON public."sales_salessettlement" ("status");
CREATE INDEX IF NOT EXISTS "sales_salessettlement_created_by_idx"
  ON public."sales_salessettlement" ("created_by_id");
CREATE INDEX IF NOT EXISTS "sales_salessettlement_customer_idx"
  ON public."sales_salessettlement" ("customer_id");
CREATE INDEX IF NOT EXISTS "sales_salessettlement_invoice_idx"
  ON public."sales_salessettlement" ("invoice_id");

ALTER TABLE public."sales_salessettlement" ENABLE ROW LEVEL SECURITY;

-- Prevent the later Django migration from trying to recreate objects repaired above.
INSERT INTO public."django_migrations" ("app", "name", "applied")
SELECT 'sales', '0003_salesinvoice_settled_amount_and_more', now()
WHERE NOT EXISTS (
  SELECT 1 FROM public."django_migrations"
  WHERE "app" = 'sales' AND "name" = '0003_salesinvoice_settled_amount_and_more'
);

COMMIT;
